@startuml

class User {
  +username : string
  +password : string
}

class Player extends User {}

class Admin extends User {}

class Game {
  +name : string
}

class HallOfFame {
  +highScore : int
}

class Block {
  +color : string
  +points : int
}

class Level {
  +number : int
  +isRandom : boolean
}

class GridPosition {
  +x : int
  +y : int
}

class GameSettings {
  +minSpeed : float
  +speedIncreaseFactor : float
  +maxLength : float
  +minLength : float
}

class GameSession {
  +lives : int
  +totalScore : int
}

class BlockPlacement {
  +gridPosition : GridPosition
}

Admin "0..1" -- "1" Game : manages
Game "1" *-- "1" HallOfFame
Game "1" *-- "*" Level
Game "1" *-- "1" GameSettings
Game "1" *-- "*" BlockPlacement
Level "1" *-- "*" BlockPlacement
BlockPlacement "*" -- "1" Block
BlockPlacement "*" -- "1" GridPosition

Admin "0..1" -- "0..1" Game : admin_of
Player "0..*" -- "0..*" Game : plays

Game "1" -- "0..*" GameSession : has
Player "1" -- "0..*" GameSession : participates_in

@enduml

